scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    /*
    00726 - 소속부유형코드
    01361 - 소속부변경구분코드
    01362 - 벤처유형코드
    */
    var arrCid = [{
        cid: "SECT_TP_CD",
        cnm: "cmb_BFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_TP_CD",
        cnm: "cmb_AFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_CHG_TP_CD",
        cnm: "cmb_SECT_CHG_TP_CD"
    }, {
        cid: "SECT_INVSTG_TP_CD",
        cnm: "cmb_AFCHG_SECT_INVSTG_TP_CD"
    }, {
        cid: "SECT_CHG_RSN_CD",
        cnm: "cmb_SECT_CHG_RSN"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SECT_TP_CD','SECT_TP_CD','SECT_CHG_TP_CD','SECT_INVSTG_TP_CD','SECT_CHG_RSN_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                if (arrCid[i].cid == "01362") {
                    if (dts_Cod.getCellData(j, "VALUE") == "10") {
                        strCbd = strCbd + "^-----------------------------------------------------";
                    }
                }
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_extr_read_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=SECT_TYP_CHG_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.select.extr.search" + "&{P}param01=" + scwin.vAcptNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    scwin.fn_file_read_sync();
};
scwin.fn_file_read_sync = function() {
    if (scwin.vAcptNo != "") {
        //컨버젼하기가 어려워 제외됨..
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=SECT_TYP_CHG_APPROV_ATTACHFILE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.select.attachfile" + "&{P}param01=" + scwin.vAcptNo;
        dts_File.DataID = encodeURI(url);
        dts_File.Reset();
    } else {
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=SECT_TYP_CHG_CERT_ATTACHFILE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.select.cert.attachfile" + "&{P}param01=" + scwin.vBzProcsNo;
        dts_File.DataID = encodeURI(url);
        dts_File.Reset();
    }
};
scwin.fn_read_sync = function() {
    var url = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readMarketAction&inputMessageId=SECT_TYP_CHG_INOUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    scwin.fn_file_read_sync();
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECT_CHG_TP_CD) == "") {
        $c.win.alert("[소속부변경구분]을 선택하세요.");
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if (scwin.vSECT_CHG_TP_CD == 'N') {
        if (scwin.vSECT_CHG_TP_CD != $c.stf.getObjectValue(cmb_SECT_CHG_TP_CD)) {
            $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [소속부변경구분]항목을 변경할 수 없습니다.");
            cmb_SECT_CHG_TP_CD.focus();
            return false;
            //심사팀에서 신규상장시 입력한 자료라서 수정 불가.
        }
    }
    if ($c.stf.getObjectValue(cmb_SECT_CHG_TP_CD) == "") {
        $c.win.alert("[소속부변경구분]을 선택하세요.");
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECT_CHG_TP_CD) != "N") {
        //신규상장
        if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == "") {
            $c.win.alert("[변경전 소속부] 항목값이  없습니다.");
            cmb_BFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == "") {
        $c.win.alert("[변경후 소속부]를 선택하세요.");
        cmb_AFCHG_SECT_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CHG_DD) == "") {
        $c.win.alert("[변경일]을 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_CHG_DD)) {
        $c.win.alert("[변경일]을 현재일이후로 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_SECT_STRT_DD) == "") {
        if ($c.stf.getObjectValue(edt_SECT_END_DD) != "") {
            $c.win.alert("[소속부유효시작일]을 입력하세요.");
            edt_SECT_STRT_DD.focus();
            return false;
        }
    } else {
        if ($c.stf.getObjectValue(edt_SECT_END_DD) == "") {
            $c.win.alert("[소속부유효종료일]을 입력하세요.");
            edt_SECT_END_DD.focus();
            return false;
        }
        if (parseInt($c.stf.getObjectValue(edt_SECT_STRT_DD), 10) > parseInt($c.stf.getObjectValue(edt_SECT_END_DD), 10)) {
            $c.win.alert("[소속부유효종료일]은 [소속부유효시작일]보다 작아야 합니다. 다시 입력해주세요");
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_AFCHG_SECT_INVSTG_TP_CD) == "") {
        $c.win.alert("[소속부 심사구분]를 선택하세요.");
        cmb_AFCHG_SECT_INVSTG_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == "4") {
        //기술성장기업부
        if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == "2" || $c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == "3") {
            $c.win.alert("변경전 소속부가 기술성장기업부일 경우 우량기업부로 변경만 가능합니다.");
            cmb_AFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == "2" || //벤처 
        $c.stf.getObjectValue(cmb_BFCHG_SECT_TP_CD) == "3") {
        //중견
        if ($c.stf.getObjectValue(cmb_AFCHG_SECT_TP_CD) == "4") {
            $c.win.alert("변경전 소속부가 벤처나 중견일 경우 우량기업부로 변경만 가능합니다.");
            cmb_AFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    return true;
};
scwin.fn_duplicate_check = function() {
    var url = "/SectionTypeChange.do?method=checkDuplicate&inputMessageId=SECT_TYP_CHG_DUP_CHK_OUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&CHG_DD=" + $c.stf.getObjectValue(edt_CHG_DD);
    dts_DUP_CHK.DataID = encodeURI(url);
    dts_DUP_CHK.Reset();
    return dts_DUP_CHK.getCellData(1, "DUP_CHK");
};


//인증자격
scwin.fn_AhthAdm = function(type) {
    if (scwin.type == "1") {
        var url = "/listingCommon.do?method=listGeneral&outputMessageId=SECT_TYP_CHG_AHTH_ADM_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.ahthacpt.select" + "&{P}param01=" + scwin.vAcptNo;
        dts_AhthAdm.DataID = encodeURI(url);
        dts_AhthAdm.Reset();
    } else {
        var url = "/listingCommon.do?method=listGeneral&outputMessageId=SECT_TYP_CHG_AHTH_ADM_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.ahthprocs.select" + "&{P}param01=" + scwin.vBzProcsNo;
        dts_AhthAdm.DataID = encodeURI(url);
        dts_AhthAdm.Reset();
    }
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (scwin.fn_duplicate_check() == 'Y') {
            $c.win.alert("[변경일]이 동일한 일자로 이미  입력되었습니다.");
            return;
        }
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_INSERT);

        /*
        vBzProcsNo = fn_getNewBzProcNo( dts_BzProcsNo );

        if (vBzProcsNo.length != 14) {
        	alert(getMessageParam("MSG-0010", ""));
        } else {

        	//dts_Item.NameValue(1, "BZ_PROCS_NO") = vBzProcsNo;
        	//alert('[JOB_TYPE]'+dts_Item.NameValue(1, "JOB_TYPE") );
        	//alert('[vSPOT_ISU_TRD_MKT_TP_CD]'+vSPOT_ISU_TRD_MKT_TP_CD );

        	fn_trs(TR_JOB_INSERT);
        }
        */

    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_delete = function() {
    if ($c.stf.getObjectValue(edt_APPROV_DDTM) != "") {
        $c.win.alert("승인처리가 완료된 후 삭제 할 수 없습니다.");
        return;
    }
    scwin.TR_JOB = 'D';
    if (scwin.vSECT_CHG_TP_CD == 'N') {
        $c.win.alert("[소속부변경구분]값이 '신규상장'이면 삭제 할 수 없습니다.");
        cmb_SECT_CHG_TP_CD.focus();
        return;
        //심사팀에서 신규상장시 입력한 자료라서 삭제 불가(신규상장한건도 삭제처리됨.).
    }
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.fn_trs(TR_JOB_DELETE);
};
scwin.fn_BfSectInvstgTpCd = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=SECT_TYP_CHG_INVSTG_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.bfchgsectinvstgtpcd.select" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_bfSectInvstg.DataID = encodeURI(url);
    dts_bfSectInvstg.Reset();
};
scwin.fn_trs = function(jobType) {
    //소속부 변경전 심사코드 
    scwin.fn_BfSectInvstgTpCd();
    dts_Item.setCellData(1, "JOB_TYPE", jobType);
    dts_Item.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
    dts_Item.setCellData(1, "LIST_BZ_TP_CD", LIST_BZ_TP_CD_234);
    dts_Item.setCellData(1, "SPOT_ISU_TRD_MKT_TP_CD", scwin.vSPOT_ISU_TRD_MKT_TP_CD);
    dts_Item.setCellData(1, "BFCHG_SECT_INVSTG_TP_CD", dts_bfSectInvstg.getCellData(1, "AFCHG_SECT_INVSTG_TP_CD"));
    var vScrenProcTpCd;
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }

    //alert('[dts_Item]'+dts_Item.text);
    trs_Save.Action = $c.lc.fn_encodeNSession("/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveMarketAction");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item,I:pFile1=dts_File)";
    trs_Save.Post();
};
scwin.fn_popopSW = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=SECT_TYP_CHG_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.revwrlog.sw.select" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_sw.DataID = encodeURI(url);
    dts_sw.Reset();
};
scwin.fn_revwr = function() {
    scwin.TR_JOB = '검토처리';
    scwin.pLogType = "1";
    var res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.TR_JOB));
    if (res) {
        scwin.fn_trslog('1');
    }
};
scwin.fn_approve = function() {
    if ($c.stf.getObjectValue(edt_REVW_DDTM) == "") {
        $c.win.alert("검토처리가 완료된 후 승인처리를 할 수 있습니다.");
        return;
    }
    scwin.TR_JOB = '승인처리';
    scwin.pLogType = "2";
    var res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.TR_JOB));
    if (res) {
        scwin.fn_trslog('2');
    }
};
scwin.fn_trslog = function(logTyp) {
    dts_Item.setCellData(1, "APPROV_TYPE", logTyp);
    dts_Item.setCellData(1, "REVWR_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "APPROV_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);

    //alert('[dts_Item]'+dts_Item.text);
    trs_Log.Action = $c.lc.fn_encodeNSession("/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveApprovLog");
    trs_Log.KeyName = "toinb_dataid4";
    trs_Log.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Log.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_Search;
    fr_fn_list_sync();
};
scwin.fn_filedown = function(dtsObj) {
    var vKey = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "DISCLS_DOC_NO");
    var attach_seq = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ATTACH_SEQ");
    if (scwin.vAcptNo != "") {
        location.href = "/filedownload.do?file_id=" + vKey + "&attach_seq=" + attach_seq + "&gubun=12";
    } else {
        location.href = "/filedownload.do?file_id=" + vKey + "&attach_seq=" + attach_seq + "&gubun=23";
    }
};



/********************************************** 
 * 함수명   : Print()
 * 설명       : 화면을 인쇄한다. 
 ***********************************************/
scwin.fn_print = function() {
    var url = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_05 + "&method=readSectChgReport&inputMessageId=SECT_TYP_CHG_REPORT_OUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Report.DataID = encodeURI(url);
    dts_Report.Reset();
    var pdf_rptname = "RLDSTF00009";
    var userParam = [{
        uid: "ISU_SRT_CD",
        unm: dts_Report.getCellData(1, "ISU_SRT_CD")
    }, {
        uid: "ISU_KOR_ABBRV",
        unm: dts_Report.getCellData(1, "ISU_KOR_ABBRV")
    }, {
        uid: "FST_EXAMPRN_EMP_NM",
        unm: dts_Report.getCellData(1, "FST_EXAMPRN_EMP_NM")
    }, {
        uid: "APPL_DD",
        unm: $c.stf.FormatDateEx(dts_Report.getCellData(1, "APPL_DD"))
    }, {
        uid: "CHG_DD",
        unm: $c.stf.FormatDateEx(dts_Report.getCellData(1, "CHG_DD"))
    }, {
        uid: "SECT_CHG_TP_NM",
        unm: dts_Report.getCellData(1, "SECT_CHG_TP_NM")
    }, {
        uid: "BFCHG_SECT_TP_NM",
        unm: dts_Report.getCellData(1, "BFCHG_SECT_TP_NM")
    }, {
        uid: "AFCHG_SECT_TP_NM",
        unm: dts_Report.getCellData(1, "AFCHG_SECT_TP_NM")
    }, {
        uid: "SECT_STRT_DD",
        unm: $c.stf.FormatDateEx(dts_Report.getCellData(1, "SECT_STRT_DD"))
    }, {
        uid: "SECT_END_DD",
        unm: $c.stf.FormatDateEx(dts_Report.getCellData(1, "SECT_END_DD"))
    }, {
        uid: "AFCHG_SECT_INVSTG_TP_NM",
        unm: dts_Report.getCellData(1, "AFCHG_SECT_INVSTG_TP_NM")
    }, {
        uid: "SECT_CHG_RSN",
        unm: dts_Report.getCellData(1, "SECT_CHG_RSN")
    }, {
        uid: "REMK",
        unm: dts_Report.getCellData(1, "REMK")
    }, {
